import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Provider v2 to v3 migration boundary","description":"","frontmatter":{},"headers":[],"relativePath":"release/migrations/v2-to-v3.md","filePath":"release/migrations/v2-to-v3.md"}'),s={name:"release/migrations/v2-to-v3.md"};function i(c,e,n,d,h,l){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="provider-v2-to-v3-migration-boundary" tabindex="-1">Provider v2 to v3 migration boundary <a class="header-anchor" href="#provider-v2-to-v3-migration-boundary" aria-label="Permalink to &quot;Provider v2 to v3 migration boundary&quot;">​</a></h1><p>The next provider release published from this repository MUST be a major, <code>3.0.0</code>. Provider <code>v2.1.1</code> was published carrying 24 resource types: the 15 v1beta1 Edge Platform Family resources and the nine v1alpha2 resources (<code>takoform_edge_worker</code>, <code>takoform_relational_database</code>, <code>takoform_object_bucket</code>, <code>takoform_key_value_store</code>, <code>takoform_queue</code>, <code>takoform_schedule</code>, <code>takoform_container_service</code>, <code>takoform_stateful_entity</code>, <code>takoform_vector_index</code>). The v1alpha2 epoch was withdrawn (<a href="./../../spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>), so the provider built from this repository exposes only the 15 Family resources. Removing a resource type is a breaking schema change; SemVer makes that a major, and this document is the migration contract that release must ship with.</p><h2 id="the-nine-have-no-successors" tabindex="-1">The nine have no successors <a class="header-anchor" href="#the-nine-have-no-successors" aria-label="Permalink to &quot;The nine have no successors&quot;">​</a></h2><p>No v1beta1 resource replaces a v1alpha2 resource. The Edge <code>ObjectBucket</code> deliberately registers as <code>takoform_edge_object_bucket</code> so the withdrawn <code>takoform_object_bucket</code> resource type is never reoccupied with a different contract (<a href="./../../spec/decisions/0030-a-form-line-moves-a-terraform-resource-type-may-not.html">decision 0030</a>). There is no automatic state migration, import mapping, or renamed successor: the two epochs&#39; Forms are different contracts, and pretending otherwise would claim a portable migration that does not exist.</p><h2 id="what-existing-state-does" tabindex="-1">What existing state does <a class="header-anchor" href="#what-existing-state-does" aria-label="Permalink to &quot;What existing state does&quot;">​</a></h2><p>An operator holding state for any of the nine chooses one of three explicit paths:</p><ol><li><strong>Stay pinned.</strong> <code>version = &quot;= 2.1.1&quot;</code> (or <code>= 2.0.0</code>) keeps working against a host that still serves the v1alpha2 lane. Published Registry versions are immutable; nothing removes them.</li><li><strong>Forget.</strong> <code>terraform state rm</code> / <code>tofu state rm</code> removes the resource from state without touching the remote object. The host object survives and stops being managed.</li><li><strong>Destroy.</strong> <code>terraform destroy -target</code> / <code>tofu destroy -target</code> while still pinned to v2, before upgrading. This is the only path that removes the remote object.</li></ol><p>Upgrading to <code>3.0.0</code> with any of the nine still in state fails closed: the resource type no longer exists in the provider, and both CLIs refuse the plan before any lifecycle request is made. Nothing is silently dropped.</p><h2 id="obligations-the-3-0-0-release-carries" tabindex="-1">Obligations the 3.0.0 release carries <a class="header-anchor" href="#obligations-the-3-0-0-release-carries" aria-label="Permalink to &quot;Obligations the 3.0.0 release carries&quot;">​</a></h2><ul><li>This document ships with the release and its notes name it.</li><li>The signed Registry readback lane retired with the withdrawn epochs&#39; tooling must be rebuilt for the 15-resource surface before the release&#39;s publication can be called Registry-verified (<a href="./../../spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>); the package-publication step of <a href="./../../spec/decisions/0041-form-packages-publish-with-the-provider-release.html">decision 0041</a> is rebuilt the same way when the publication blockers clear.</li><li><code>release/version.json</code> stays at the published <code>2.1.1</code> descriptor until the owner release flow assigns <code>3.0.0</code>; a repository test holds the descriptor to be either the published version or a <code>3.x</code> value, so a <code>2.x</code> successor cannot be cut by habit.</li></ul>',10)])])}const u=o(s,[["render",i]]);export{m as __pageData,u as default};
